    "passage": "【全國最老聚落——平溪「不老長智村」】\n依據世界衛生組織定義，65 歲以上老年人口佔總人口比率達 7% 時稱為「高齡化社會」，達到 14% 是「高齡社會」，達 20% 稱為「超高齡社會」。根據內政部統計我國目前邁入超高齡社會的縣市有：嘉義縣、臺北市、南投縣、雲林縣、基隆市和屏東縣。另外，新北市平溪區曾是煤礦重鎮，現在卻成為全臺最老的地方。西元 2025 年平溪的老年人口比例已突破 36%，意指每三個人中就有一位是長輩。由於年輕人外流，這裡普遍出現「老老相依」（老夫妻互相照顧）或「獨居長輩」的現象，照顧壓力常讓家庭陷入困境。\n\n為了應對這個挑戰，新北市政府與民間團體聯手推動「不老長智村」計畫，目標是讓長輩做到「獨居不孤獨」：一、化被動為主動：民間團體推動「獨老處方箋」，由志工將原本在據點的活動直接帶進長輩家中，讓原本孤單的長輩能與鄰里重新建立連結。二、整合資源平台：區公所結合了衛生所、派出所與志工，共同守護長輩身心健康。例如，與醫院合作開闢「失智篩檢綠色通道」，讓長輩能快速得到醫療幫助。三、友善空間改造：為了讓長輩行動安全，政府整平老街路面、開闢公園，並舉辦課程讓鄰里認識失智症。\n\n學者認為透過學習、社會參與及鄰里互助，平溪的經驗可以成為範本，證明獨居生活也可以過得很精彩、很有尊嚴。",
