    "passage": "　　臺中市由於各項交通建設完善，以及臺中工業區、精密機械園區、中部科學園區等陸續設立，讓臺中市逐漸成為中部地區交通運輸、經濟發展的重心，吸引人口移入，成為臺灣第二大都市。\n　　臺中市除了有國立臺灣美術館、國立自然科學博物館等文化場館，還有百貨公司及各式商圈，提供臺中市及彰化縣、南投縣等周邊縣市居民各項生活資源。彰化縣、南投縣也能提供農、漁、畜牧業產品給臺中市，彼此透過交通網路互動連結，逐漸形成一個共同的生活圈。\n　　新北市在臺北市都市化快速發展時，有些工廠逐漸從臺北市移往新北市；同時中南部有許多人北上尋找工作機會或定居，也促進新北市的工商業發展與人口增加。隨著房價上漲，有些人雖然在臺北市工作，但選擇居住在房價相對較低的新北市。現今新北市的居民超過四百萬人，已是臺灣人口最多的都市。\n　　由於部分區域人口密集，新北市現在也面臨了許多都市問題，其中交通建設一直是民眾所關注的議題，尤其上下班時間容易塞車，更令民眾苦惱。為了改善交通擁擠問題，政府鼓勵民眾使用大眾運輸，也持續興建捷運，擴大交通運輸網路。",
